57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    /**
61	     * Syntactic email validation: a non-empty local part, a single '@', and a
62	     * domain with at least one dot-separated label ending in a letter-only TLD.
63	     */
64	    private static final Pattern EMAIL_PATTERN =
65	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
66	
